import pg from "pg";

const pool = new pg.Pool();
const sql = 'SELECT authors.name, books.title FROM books INNER JOIN authors ON books.author_id = authors.id ORDER BY books.title';
const authors = (await pool.query('SELECT * FROM authors')).rows;
const books = (await pool.query('SELECT * FROM books')).rows;
const byId = Object.fromEntries(authors.map((a) => [a.id, a.name]));
const rows = books
  .map((b) => ({ name: byId[b.author_id], title: b.title }))
  .sort((x, y) => (x.title < y.title ? -1 : x.title > y.title ? 1 : 0));
globalThis.result = { sql, rows };
await pool.end();

