import pg from "pg";

const pool = new pg.Pool();
const sql = 'SELECT users.name, orders.amount FROM users LEFT JOIN orders ON orders.user_id = users.id';
const users = (await pool.query('SELECT * FROM users')).rows;
const orders = (await pool.query('SELECT * FROM orders')).rows;
const rows = users.flatMap((u) => {
  const own = orders.filter((o) => o.user_id === u.id);
  if (!own.length) return [{ name: u.name, amount: null }];
  return own.map((o) => ({ name: u.name, amount: o.amount }));
});
rows.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
globalThis.result = { sql, rows };
await pool.end();

