import pg from "pg";

const pool = new pg.Pool();
const sql = 'SELECT users.name, COALESCE(SUM(orders.amount), 0) AS total FROM users LEFT JOIN orders ON orders.user_id = users.id GROUP BY users.name ORDER BY total DESC';
const users = (await pool.query('SELECT * FROM users')).rows;
const orders = (await pool.query('SELECT * FROM orders')).rows;
const rows = users.map((u) => ({
  name: u.name,
  total: orders.filter((o) => o.user_id === u.id).reduce((s, o) => s + o.amount, 0),
}));
rows.sort((a, b) => b.total - a.total);
globalThis.result = { sql, rows };
await pool.end();

