import pg from "pg";

const pool = new pg.Pool();
globalThis.result = { sql: 'CREATE INDEX idx_events_user ON events (user_id)' };
const rows = (await pool.query('SELECT * FROM events')).rows;
const index = new Map();
for (const r of rows) {
  if (!index.has(r.user_id)) index.set(r.user_id, []);
  index.get(r.user_id).push(r.id);
}
export function indexFor(userId) {
  return index.get(userId) || [];
}
await pool.end();

