globalThis.result = { sql: 'CREATE INDEX idx_sessions_token ON sessions (token) INCLUDE (user_id)' };
const rows = (await pool.query('SELECT * FROM sessions')).rows;
const byToken = Object.fromEntries(rows.map((r) => [r.token, r.user_id]));
export function lookupByToken(token) {
  return byToken[token] === undefined ? null : byToken[token];
}
