import pg from "pg";

const pool = new pg.Pool();
const rows = (await pool.query('SELECT * FROM logs WHERE level = $1', ['error'])).rows;
const total = (await pool.query('SELECT COUNT(*) AS n FROM logs')).rows[0].n;
globalThis.result = {
  sql: 'CREATE INDEX idx_logs_level ON logs (level)',
  rows,
  fraction: Math.round((rows.length / total) * 1000) / 1000,
};
await pool.end();
